// ── Parse do CSV de investimentos ───────────────────────────────────────────
// O HTTP Request devolve o data.csv como texto puro. Aqui ele vira um array
// de objetos { perfil, produto, minimo, rentabilidade }.

const bruto = $json.data ?? $json.body ?? $json;
const texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);

const linhas = texto.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
const cabecalho = linhas[0].split(',').map((h) => h.trim());

const investimentos = linhas.slice(1).map((linha) => {
  const colunas = linha.split(',').map((c) => c.trim());
  const obj = {};
  cabecalho.forEach((h, i) => {
    obj[h] = colunas[i] ?? '';
  });
  // "minimo" vem como texto no CSV; normalizamos para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, '')) || 0;
  return obj;
});

return [{ json: { investimentos } }];

// ── Cruzamento perfil x investimento + mensagem estática (MVP) ──────────────
// Entrada: item combinado pelo Merge -> clientes (webhook) + investimentos (CSV)

const entrada = $input.first().json;
const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];
const investimentos = entrada.investimentos ?? [];

// Etapa 4 do desafio: templates fixos por perfil de investidor
const TEMPLATES = {
  Conservador:
    'Olá, {nome}! Pelo seu perfil Conservador, a prioridade é segurança e previsibilidade. ' +
    'Com o saldo de {saldo}, uma boa porta de entrada é {produto} (aplicação mínima de {minimo}, rentabilidade {rentabilidade}).',
  Moderado:
    'Olá, {nome}! Seu perfil Moderado pede um mix equilibrado entre renda fixa e variável. ' +
    'Com o saldo de {saldo}, vale considerar {produto} (aplicação mínima de {minimo}, rentabilidade {rentabilidade}).',
  Arrojado:
    'Olá, {nome}! Como investidor Arrojado, você aceita mais volatilidade em troca de retorno. ' +
    'Com o saldo de {saldo}, {produto} faz sentido (aplicação mínima de {minimo}, rentabilidade {rentabilidade}).',
};

const brl = (v) =>
  Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

// "R$ 12.500,00" -> 12500
const paraNumero = (texto) => {
  if (typeof texto === 'number') return texto;
  const limpo = String(texto).replace(/[^\d,]/g, '').replace(',', '.');
  return Number(limpo) || 0;
};

const recomendacoes = clientes.map((cliente) => {
  const saldo = paraNumero(cliente.saldo);
  const doPerfil = investimentos.filter((i) => i.perfil === cliente.perfil);

  // Preferimos o produto mais "alto" que o saldo do cliente já alcança.
  const elegiveis = doPerfil.filter((i) => saldo >= i.minimo);
  const escolhido =
    (elegiveis.length ? elegiveis : doPerfil).sort((a, b) => b.minimo - a.minimo)[0] ?? null;

  if (!escolhido) {
    return {
      ...cliente,
      saldo_numerico: saldo,
      produto: null,
      mensagem: `Olá, ${cliente.nome}! Ainda não temos uma opção cadastrada para o perfil ${cliente.perfil}.`,
      alerta: 'nenhum produto encontrado para o perfil',
    };
  }

  const mensagem = (TEMPLATES[cliente.perfil] ?? TEMPLATES.Moderado)
    .replace('{nome}', cliente.nome)
    .replace('{saldo}', brl(saldo))
    .replace('{produto}', escolhido.produto)
    .replace('{minimo}', brl(escolhido.minimo))
    .replace('{rentabilidade}', escolhido.rentabilidade);

  return {
    ...cliente,
    saldo_numerico: saldo,
    produto: escolhido.produto,
    minimo: escolhido.minimo,
    rentabilidade: escolhido.rentabilidade,
    atende_minimo: saldo >= escolhido.minimo,
    mensagem,
  };
});

return [
  {
    json: {
      ok: true,
      gerado_em: new Date().toISOString(),
      origem: 'templates estaticos (MVP)',
      total_clientes: clientes.length,
      total_investimentos: investimentos.length,
      recomendacoes,
    },
  },
];
